create or replace function public.create_boq_addition(p_item_id uuid,p_description text,p_quantity numeric,p_uom text,p_unit_rate numeric,p_requester_type text,p_reason text,p_requested_by_name text,p_approval_reference text default null,p_notes text default null,p_is_stock_item boolean default true,p_owner_type text default 'KONTRAKTOR') returns public.boq_additions language plpgsql security definer set search_path=public as $$ declare v_item_id uuid;v_code text;v_result public.boq_additions%rowtype;v_desc text;begin if auth.uid() is null then raise exception 'Authentication required';end if;if public.current_user_role() not in ('admin','site_manager') then raise exception 'Insufficient role to create BOQ addition';end if;if p_quantity is null or p_quantity<=0 or p_unit_rate is null or p_unit_rate<0 then raise exception 'Quantity and rate are invalid';end if;if coalesce(trim(p_uom),'')='' or coalesce(trim(p_reason),'')='' or coalesce(trim(p_requested_by_name),'')='' then raise exception 'UOM, reason and requester are required';end if;if p_requester_type not in ('CLIENT','CONTRACTOR') then raise exception 'Invalid requester type';end if;if p_owner_type not in ('KONTRAKTOR','IMK') then raise exception 'Invalid item ownership';end if;v_code:='ADD-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS')||'-'||upper(substr(encode(gen_random_bytes(3),'hex'),1,6));if p_item_id is null then if coalesce(trim(p_description),'')='' then raise exception 'Description is required for a new item';end if;insert into public.boq_items(boq_code,description,category,quantity,uom,unit_rate,remarks,source_sheet,source_row,is_active,is_stock_item) values(v_code,trim(p_description),'PEKERJAAN TAMBAH',0,trim(p_uom),p_unit_rate,case when p_owner_type='IMK' then 'By IMK' else 'By kontraktor' end,'PEKERJAAN TAMBAH',null,true,coalesce(p_is_stock_item,true)) returning id into v_item_id;v_desc:=trim(p_description);else select id,description into v_item_id,v_desc from public.boq_items where id=p_item_id and is_active=true;if not found then raise exception 'BOQ item not found';end if;end if;insert into public.boq_additions(addition_code,item_id,description,quantity,uom,unit_rate,requester_type,chargeable_to_client,reason,requested_by_name,approval_reference,notes,created_by,billing_status) values(v_code,v_item_id,coalesce(nullif(trim(p_description),''),v_desc),p_quantity,trim(p_uom),p_unit_rate,p_requester_type,p_requester_type='CLIENT',trim(p_reason),trim(p_requested_by_name),nullif(trim(p_approval_reference),''),nullif(trim(p_notes),''),auth.uid(),case when p_requester_type='CLIENT' then 'BELUM_DITAGIHKAN' else 'TIDAK_DITAGIHKAN' end) returning * into v_result;return v_result;end $$;revoke all on function public.create_boq_addition(uuid,text,numeric,text,numeric,text,text,text,text,text,boolean,text) from public,anon;grant execute on function public.create_boq_addition(uuid,text,numeric,text,numeric,text,text,text,text,text,boolean,text) to authenticated;